package io.github.diodeme.ji.remote;

import java.nio.file.Path;
import java.util.List;
import java.util.Optional;
import java.util.OptionalInt;

/** Read-only probe: the production scanner, against the authorized target from .env. */
public final class HostKeyScanProbe {
    public static void main(String[] args) {
        var target = new SshTarget(args[0], args.length > 1 ? Optional.of(args[1]) : Optional.empty(),
                OptionalInt.empty(), Optional.empty());
        var scanner = new SshHostKeyScanner();
        var scan = scanner.scan(new SystemProcessRunner(), target);
        System.out.println("clientOrder=" + ... hmm, can't read details
        System.out.println("keys=" + scan.keys().size() + " kexUnsupported=" + scan.clientKexUnsupported());
        for (String key : scan.keys()) System.out.println(SshKnownHosts.parse(key).map(SshKnownHosts.HostKey::fingerprint).orElse("unparsable"));
    }
}
```

